        while (L >= 0) {
            int r = 0;
            for (int i = 0; i < n; i++) {
                r = max(r, simulate(i, x[i], y[i], L));
            }
            R = max(R, r);
            L -= 0.1;
        }
        cout << R << endl;
    }
    return 0;
