  for (int i = 0; i < R; i++) {
    vector<pair<int, int>> thisList;
    int qMask = 0, bMask = 0;
    for (int j = 0; j < C; j++) {
      qMask <<= 1;
      if (tbl[i][j] == '?') qMask |= 1;
      else if (tbl[i][j] == '#') bMask |= 1;
    }
    for (auto it : prev) {
      int curMask = it.first, happy = it.second;
      for (int i1 = 0; i1 < C; i1++) if ((qMask >> i1) & 1) {
        for (int i2 = 0; i2 < C; i2++) {
          if (i1 == i2) continue;
          if ((curMask >> i2) & 1) {
            if (abs(i1 - i2) == 1) {
              happy = max(happy, (int)1e9);
              break;
            } else {
              happy--;
            }
          }
        }
        int best = -1;
        for (int mask = curMask | (1 << i1); mask <= (qMask | (1 << i1)); mask |= mask << 1) {
          if (((mask ^ (mask >> 1)) & mask) == 0 && !(mask & bMask)) {
            best = max(best, happy + countBits[mask]);
          }
        }
        if (best != -1) thisList.push_back({mask, best});
      }
    }
    prev = thisList;
    if (prev.empty()) return 0;
    ans = max(ans, prev[0].second);
  }
  return ans;
}

