  Circle(Point center, double radius) : center(center), radius(radius) {}
};

struct Line {
  Point p1, p2;
  Line() : p1(0, 0), p2(0, 0) {}
  Line(Point p1, Point p2) : p1(p1), p2(p2) {}
};

double sqr(double x) { return x * x; }

double dist(Point p1, Point p2) { return sqrt(sqr(p1.x - p2.x) + sqr(p1.y - p2.y)); }

double area(double w, double h) { return w * h; }

double area(Circle circle) { return PI * circle.radius * circle.radius; }

double area(Line line, double h) {
  return area(line.p2.x - line.p1.x, h);
}

double area(Circle circle, Line line) {
  double d = dist(circle.center, line.p1);
  if (d + circle.radius <= EPS) return 0;
  if (d - circle.radius > line.p2.x - line.p1.x + EPS) return area(line, circle.center.y);
  double h = sqrt(sqr(circle.radius) - sqr(d));
  double w = line.p2.x - line.p1.x;
  double intersect = 2 * asin(h / circle.radius) * circle.radius;
  return area(line, circle.center.y) - area(Circle(circle.center, h), line);
}

