void genCol() {
  map<string, int> mp;
  int cnt = 0;
  for (auto u : col_s) {
    if (!mp.count(u)) {
      mp[u] = cnt++;
      first.push_back(1);
    } else {
      first.push_back(0);
    }
    col.push_back(mp[u]);
  }
}

int getHeight(int mask) {
  vector<int> h(col.size(), 0);
  for (int i = 0; i < col.size(); i++) {
    if ((mask >> i) & 1) {
      h[col[i]]++;
    } else {
      h[col[i]] = max(h[col[i]], (int)first[i] + 1);
    }
  }
  return *max_element(h.begin(), h.end());
}

int run() {
  int n;
  cin >> n;
  col_s.resize(n);
  for (auto &u : col_s) cin >> u;
  int m = (n + 1) / 2;
  genCol();
  vector<int> dp(1 << m, -1);
  dp[0] = 0;
  for (int mask = 0; mask < (1 << m); mask++) {
    dp[mask] = getHeight(mask);
    for (int i = 0; i < m; i++) {
      if (!((mask >> i) & 1)) {
        if (dp[mask] > dp[mask | (1 << i)]) dp[mask | (1 << i)] = dp[mask];
      }
    }
  }
  return dp[(1 << m) - 1];
}

