template <typename T>
struct Edge {
    int target;
    T cost;
    Edge(int target, T cost) : target(target), cost(cost) {}
};

template <typename T>
class Dijkstra {
private:
    int vertex_num;
    vector<T> distances;
    vector<vector<Edge<T>>> edges;

public:
    Dijkstra(int vertex_num) : vertex_num(vertex_num) {
        distances.assign(vertex_num, -1);
        edges.resize(vertex_num);
    }

    void addEdge(int source, int target, T cost) {
        edges[source].emplace_back(target, cost);
    }

    void update(int source) {
        priority_queue<pair<T, int>> pq;
        pq.emplace(0, source);
        distances[source] = 0;

        while (!pq.empty()) {
            auto [dist, vertex] = pq.top(); pq.pop();
            if (-dist > distances[vertex]) continue;

            for (auto& edge : edges[vertex]) {
                T new_dist = dist - edge.cost;
                if (new_dist > distances[edge.target]) {
                    distances[edge.target] = new_dist;
                    pq.emplace(new_dist, edge.target);
                }
            }
        }
    }

    T getDistance(int vertex) {
        return distances[vertex];
    }
};

