struct Re {
    enum { CONCAT, DIG, STAR, OR } type;
    int value;
    Re *a, *b;
    Re(char c) : value(c), type(DIG) {}
    Re(Re *a, Re *b, int t) : a(a), b(b), type(t) {}
};

Re *nor(Re *a, Re *b) { return new Re(a, b, OR); }
Re *concat(Re *a, Re *b) { return new Re(a, b, CONCAT); }
Re *star(Re *a) { return new Re(a, nullptr, STAR); }
Re *dig(char c) { return new Re(c); }

void build(NFA &nfa, int from, int to) {
    nfa.nodes[from].eps.push_back(to);
}

Re *parse2(string s) {
    Re *e = nullptr, *t, *p = nullptr;
    stack<Re *> st;
    rep(i, 0, sz(s)) {
        switch (s[i]) {
            case '(':
                st.push(e);
                e = t = nullptr;
                break;
            case ')':
                t = st.top();
                st.pop();
                if (st.empty())
                    return t;
                p = st.top();
                st.pop();
                st.push(concat(p, t));
                break;
            case '.':
                if (st.empty())
                    st.push(e);
                p = st.top();
                st.pop();
                t = e;
                e = concat(p, t);
                st.push(e);
                break;
            case '*':
                t = st.top();
                st.pop();
                st.push(star(t));
                break;
            default:
                e = dig(s[i]);
                if (!st.empty()) {
                    p = st.top();
                    st.pop();
                    st.push(concat(p, e));
                } else
                    st.push(e);
        }
    }
    return e;
}

Re *parseOr(string s) {
    vector<Re *> regs;
    string t;
    for (char c : s) {
        if (c == '|') {
            regs.push_back(parse2(t));
            t = "";
        } else
            t += c;
    }
    regs.push_back(parse2(t));
    if (sz(regs) == 1)
        return regs[0];
    Re *ret = nor(regs[0], regs[1]);
    for (int i = 2; i < sz(regs); i++)
        ret = nor(ret, regs[i]);
    return ret;
}

