    int packages = 0;
    while (true) {
        bool all_exhausted = true;
        for (int i = 0; i < N; i++) {
            if (index[i] < P) all_exhausted = false;
        }
        if (all_exhausted) break;
        int min_quantity = Q[0][index[0]];
        int min_idx = 0;
        for (int i = 1; i < N; i++) {
            if (Q[i][index[i]] < min_quantity) {
                min_quantity = Q[i][index[i]];
                min_idx = i;
            }
        }
        int low = min_quantity * R[min_idx] / 100 - 10;
        int high = min_quantity * R[min_idx] / 100 + 10;
        bool found = false;
        for (int j = low; j <= high; j++) {
            bool ok = true;
            for (int i = 0; i < N; i++) {
                if (!can_do_it(R[i], Q[i][index[i]], j)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                found = true;
                break;
            }
        }
        if (found) {
            packages++;
            for (int i = 0; i < N; i++) {
                index[i]++;
            }
        } else {
            index[min_idx]++;
        }
    }
    return packages;
}
