bool cw(int p1, int p2, int p3) {
  return (x[p2] - x[p1]) * (y[p3] - y[p1]) - (y[p2] - y[p1]) * (x[p3] - x[p1]) > 0;
}

vector<int> convexHull(int n) {
  vector<int> convex;
  for (int i = 0; i < n; i++) {
    while (convex.size() >= 2 && cw(convex[convex.size() - 2], convex.back(), i))
      convex.pop_back();
    convex.push_back(i);
  }
  return convex;
}

bool on_line(int p1, int p2, int p3) {
  return (x[p1] - x[p3]) * (y[p2] - y[p3]) == (y[p1] - y[p3]) * (x[p2] - x[p3]);
}

