class Solver {
 private:
  vector<int> c, p, pc, l;
  bool pro(int n) {
    if (a[n].size() != b[n].size()) return false;
    if (a[n].size() == 0) return true;
    c.resize(b[n].size());
    rep(i, c.size()) c[i] = b[n][i].x;
    sort(all(c));
    rep(i, c.size()) id[b[n][i].y] = lower_bound(all(c), b[n][i].x) - c.begin();
    rep(i, c.size()) pc[id[i]] = 1;
    rep(i, a[n].size()) {
      if (id[a[n][i].y]) continue;
      int t = lower_bound(all(c), a[n][i].x) - c.begin();
      if ((t < c.size()) && (c[t] == a[n][i].x)) id[a[n][i].y] = t;
    }
    int cnt = 0;
    rep(i, pc.size()) cnt += pc[i];
    return cnt == pc.size();
  }
  bool end() {
    int t = -1;
    rep(i, pn) {
      if (p[i] == 0) return true;
      if (t == -1) t = l[i];
      if (t != l[i]) return false;
    }
    return true;
  }
  int emp() {
    int t = -1, x = INF;
    rep(i, pn) {
      if (!p[i]) return i;
      if (x > l[i]) { t = i; x = l[i]; }
    }
    return t;
  }
  bool dfs(int n) {
    if (end()) return true;
    int v = emp();
    if (v == -1) return false;
    rep(i, p[v]) {
      l[v]++;
      bool ret = pro(v);
      if (!ret) { l[v]--; continue; }
      p[v]--;
      if (dfs(n + 1)) return true;
      p[v]++;
    }
    l[v] = 0;
    return false;
  }

 public:
  void solve() {
    p.resize(pn, 0);
    l.resize(pn, 0);
    rep(i, pn) cin >> p[i];
    rep(i, pn) {
      a.emplace_back();
      rep(j, p[i]) {
        int x;
        cin >> x;
        a[i].emplace_back(x, j);
      }
    }
    rep(i, pn) {
      b.emplace_back();
      rep(j, p[i]) {
        int x;
        cin >> x;
        b[i].emplace_back(x, j);
      }
    }
    pc.resize(a[0].size());
    id.resize(a[0].size());
    if (dfs(0))
      cout << "POSSIBLE" << '\n';
    else
      cout << "IMPOSSIBLE" << '\n';
  }
};

