int UnionFind::root(int x) { return f[x] == -1 ? x : f[x] = root(f[x]); }

bool UnionFind::conn(int x, int y) {
  int rx = root(x), ry = root(y);
  if (rx == ry) return true;
  if (f[rx] > f[ry]) swap(rx, ry);
  f[ry] += f[rx];
  f[rx] = ry;
  return true;
}
