int better(int i, int j, int k, double dir) {
  if (dst(i, k) > dst(j, k))
    return j;
  double a1 = atan2(y[i] - y[k], x[i] - x[k]), a2 = atan2(y[j] - y[k], x[j] - x[k]), d = (a2 - a1) / 3.14159265358979323846;
  if (d < 0) d += 2;
  if (fabs(d - 1) < fabs(d - 3))
    return j;
  else
