class MaxFlow {
public:
    struct Edge {
        int to, cap, rev;
    };
    vector<vector<Edge>> g;
    vector<bool> used;
    int n, s, t;

    MaxFlow(int nn, int ss, int tt) {
        n = nn;
        s = ss;
        t = tt;
        g.resize(n);
        used.resize(n);
    }

    void add(int v, int u, int cap) {
        g[v].push_back({u, cap, (int)g[u].size()});
        g[u].push_back({v, 0, (int)g[v].size() - 1});
    }

    bool findPath(int v, int t) {
        if (v == t) return true;
        used[v] = true;
        for (Edge &e : g[v]) {
            if (!used[e.to] && e.cap > 0) {
                if (findPath(e.to, t)) {
                    return true;
                }
            }
        }
        return false;
    }

    int augment(int v, int t, int &res, int cap) {
        if (v == t) {
            res = cap;
            return cap;
        }
        used[v] = true;
        for (Edge &e : g[v]) {
            if (!used[e.to] && e.cap > 0) {
                int f = augment(e.to, t, res, min(cap, e.cap));
                if (f > 0) {
                    e.cap -= f;
                    g[e.to][e.rev].cap += f;
                    return f;
                }
            }
        }
        return 0;
    }

    int build() {
        int flow = 0;
        while (findPath(s, t)) {
            used.assign(n, false);
            int res = 0;
            int f = augment(s, t, res, INT_MAX);
            while (f > 0) {
                flow += f;
                f = augment(s, t, res, INT_MAX);
            }
        }
        return flow;
    }

    int mincut() {
        int flow = 0;
        for (Edge &e : g[s]) {
            flow += e.cap;
        }
        return flow;
    }
};

