const double eps = 1e-9;

struct rat {
	long long a, b;
	bool operator<(const rat& o) const { return (double)a / b < (double)o.a / o.b; }
	double value() { return (double)a / b; }
};

double calculate(vector<int> ind) {
	double ans = 1;
	for (int i : ind) {
		ans *= have[i].value();
	}
	return ans;
}

double A[maxN][maxN], rA[maxN][maxN], P[maxN][maxN], rP[maxN][maxN];

void gen(int n) {
	have.clear();
	for (int i = 1; i <= n; i++) {
		for (int j = i + 1; j <= n; j++) {
			have.push_back({i, j});
		}
	}
	sort(have.begin(), have.end());
}

void solve() {
	int n;
	cin >> n;
	have.resize(n);
	for (int i = 0; i < n; i++) { cin >> have[i].a >> have[i].b; }
	sort(have.begin(), have.end());
	for (int i = 0; i <= n; i++) {
		for (int j = 0; j <= n; j++) {
			A[i][j] = rA[i][j] = -1;
			P[i][j] = rP[i][j] = -1;
		}
	}
	A[0][0] = rA[0][0] = P[0][0] = rP[0][0] = 1;
	for (int i = 1; i <= n; i++) {
		for (int j = 0; j <= n; j++) {
			if (j > 0) A[i][j] = P[i - 1][j] + have[i - 1].value() * rA[i - 1][j - 1];
			rA[i][j] = have[i - 1].value() * P[i - 1][j - 1] + rA[i - 1][j];
		}
	}
	for (int i = n - 1; i >= 0; i--) {
		for (int j = 0; j <= n; j++) {
			if (j > 0) P[i][j] = A[i + 1][j] + rP[i + 1][j - 1];
			rP[i][j] = rA[i][j] + rP[i + 1][j];
		}
	}
	int best = n, bestVal = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j <= n; j++) {
			double now = A[i + 1][j] - rA[0][j];
			if (now > bestVal + eps) {
				best = i;
				bestVal = now;
			}
		}
	}
	vector<int> ans;
	for (int i = 0; i < best; i++) {
		if (bestVal == (A[i + 1][n] - rA[0][n])) {
			ans.push_back(i);
			bestVal -= rP[i + 1][n];
		}
	}
	cout << ans.size() << ":";
	for (int x : ans) cout << " " << x + 1;
	cout << "\n";
}

