using namespace std;

int P[1000001];
int B[1000001];
multiset<pair<int, int>> CS[1000001];
bool used[1000001];

pair<int, int> solveCase(int n, int s, int m) {
  int rides = 0, promised = 0;
  multiset<pair<int, int>> Q;
  for (int i = 1; i <= n; i++) {
    Q.insert({P[i], B[i]});
  }
  vector<pair<int, int>> toErase;
  for (auto it = Q.begin(); it != Q.end(); it++) {
    if (!used[it->first]) {
      rides++;
      used[it->first] = true;
      toErase.push_back(*it);
    }
  }
  for (auto it : toErase) {
    Q.erase(it);
  }
  for (int i = 1; i <= s; i++) {
    CS[i].clear();
  }
  for (int i = 1; i <= n; i++) {
    CS[P[i]].insert(B[i]);
  }
  for (int i = 1; i <= s; i++) {
    if (CS[i].size() > rides) {
      promised += CS[i].size() - rides;
    }
  }
  return {rides, promised};
}

