int leader(int u, int *par) {
    return par[u] == u ? u : par[u] = leader(par[u], par);
}

void merge(int u, int v, int *par, int *sz) {
    u = leader(u, par);
    v = leader(v, par);
    if (u != v) {
        if (sz[u] < sz[v])
            swap(u, v);
        par[v] = u;
        sz[u] += sz[v];
    }
}

void add(int r, int c, int *grid, int *par, int *sz) {
    int u = getIdx(r, c);
    if (r - 1 >= 0 && grid[getIdx(r - 1, c)] > 0)
        merge(u, getIdx(r - 1, c), par, sz);
    if (r + 1 < s && grid[getIdx(r + 1, c)] > 0)
        merge(u, getIdx(r + 1, c), par, sz);
    if (c - 1 >= 0 && grid[getIdx(r, c - 1)] > 0)
        merge(u, getIdx(r, c - 1), par, sz);
    if (c + 1 < m && grid[getIdx(r, c + 1)] > 0)
        merge(u, getIdx(r, c + 1), par, sz);
}

bool bridge(int *grid) {
    for (int i = 0; i < s; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[getIdx(i, j)] == 2) {
                int cnt = 0;
                if (i - 1 >= 0 && grid[getIdx(i - 1, j)] > 0)
                    cnt++;
                if (i + 1 < s && grid[getIdx(i + 1, j)] > 0)
                    cnt++;
                if (j - 1 >= 0 && grid[getIdx(i, j - 1)] > 0)
                    cnt++;
                if (j + 1 < m && grid[getIdx(i, j + 1)] > 0)
                    cnt++;
                if (cnt == 2)
                    return true;
            }
        }
    }
    return false;
}

bool fork(int *grid) {
    for (int i = 0; i < s; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[getIdx(i, j)] == 2) {
                int cnt = 0;
                if (i - 1 >= 0 && grid[getIdx(i - 1, j)] > 0)
                    cnt++;
                if (i + 1 < s && grid[getIdx(i + 1, j)] > 0)
                    cnt++;
                if (j - 1 >= 0 && grid[getIdx(i, j - 1)] > 0)
                    cnt++;
                if (j + 1 < m && grid[getIdx(i, j + 1)] > 0)
                    cnt++;
                if (cnt >= 3)
                    return true;
            }
        }
    }
    return false;
}

int dfs(int r, int c, int *grid, int *par) {
    int u = getIdx(r, c);
    if (grid[u] == 0)
        return 0;
    if (par[u] != -1)
        return par[u];
    int cnt = 1;
    if (r - 1 >= 0 && grid[getIdx(r - 1, c)] > 0)
        cnt += dfs(r - 1, c, grid, par);
    if (r + 1 < s && grid[getIdx(r + 1, c)] > 0)
        cnt += dfs(r + 1, c, grid, par);
    if (c - 1 >= 0 && grid[getIdx(r, c - 1)] > 0)
        cnt += dfs(r, c - 1, grid, par);
    if (c + 1 < m && grid[getIdx(r, c + 1)] > 0)
        cnt += dfs(r, c + 1, grid, par);
    return par[u] = cnt;
}

bool ring(int *grid) {
    int par[N * N];
    memset(par, -1, sizeof par);
    for (int i = 0; i < s; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[getIdx(i, j)] > 0) {
                if (par[getIdx(i, j)] == -1) {
                    int cnt = dfs(i, j, grid, par);
                    if (cnt >= 4)
                        return true;
                }
            }
        }
    }
    return false;
}

