const int INF = 1e9;
const int M = 1e5;
int N, P;
vector<int> R, Q[M][M], xQ[M][M][2];
int lbs[M], ubs[M];

struct Edge {
    int to, cap, rev;
};

class FordFulkerson {
    vector<vector<Edge>> g;
    vector<int> q, level;

public:
    FordFulkerson(int n) : g(n) {}

    void add_edge(int u, int v, int cap) {
        g[u].push_back({v, cap, (int)g[v].size()});
        g[v].push_back({u, 0, (int)g[u].size() - 1});
    }

    bool dfs(int u, int t, int f) {
        if (u == t) return true;
        level[u] = 1;
        q.push_back(u);
        for (auto& e : g[u]) {
            if (e.cap > 0 && level[e.to] == 0 && dfs(e.to, t, min(f, e.cap))) {
                e.cap -= f;
                g[e.to][e.rev].cap += f;
                return true;
            }
        }
        return false;
    }

    int max_flow(int s, int t) {
        int flow = 0;
        while (true) {
            q.clear();
            level.assign(g.size(), 0);
            if (!dfs(s, t, INF)) break;
            while (!q.empty()) {
                int u = q.back();
                q.pop_back();
                for (auto& e : g[u]) {
                    if (e.cap > 0 && level[u] > 0 && level[u] + 1 == level[e.to]) {
                        if (dfs(e.to, t, min(e.cap, f))) {
                            e.cap -= f;
                            g[e.to][e.rev].cap += f;
                            flow += f;
                        }
                    }
                }
            }
        }
        return flow;
    }
};

void solve() {
    cin >> N >> P >> lbs[0];
    int a;
    for (int i = 1; i <= N; i++) {
        cin >> a;
        R.push_back(a);
        cin >> ubs[i] >> lbs[i];
    }
    for (int j = 0; j < P; j++) {
        for (int i = 0; i < N; i++) {
            cin >> Q[i][j];
            xQ[i][j][0] = (Q[i][j] > lbs[i]) ? Q[i][j] - lbs[i] : 0;
            xQ[i][j][1] = (Q[i][j] > ubs[i]) ? ubs[i] - lbs[i] : Q[i][j] - lbs[i];
        }
    }

    FordFulkerson ff(N + P + 2);
    int s = N + P, t = N + P + 1;
    for (int i = 0; i < N; i++) {
        ff.add_edge(s, i, R[i]);
        for (int j = 0; j < P; j++) {
            ff.add_edge(i, N + j, xQ[i][j][1]);
        }
    }
    for (int j = 0; j < P; j++) {
        ff.add_edge(N + j, t, INF);
    }
    cout << ff.max_flow(s, t) << endl;
}

int main() {
    int t;
    cin >> t;
    while (t--) solve();
