using namespace std;

const int MOD = 1e9+7;

vector<int> f, g;
vector<int> fact, inv_fact;

int input() {
  int n, x;
  cin >> n >> x;
  return x;
}

void calc_fg() {
  f.resize(input());
  f[0] = 1;
  for (int i = 1; i < f.size(); i++) f[i] = (1LL * f[i-1] * i) % MOD;
  g.resize(f.size());
  g[f.size()-1] = inv(f[f.size()-1]);
  for (int i = f.size()-2; i >= 0; i--) g[i] = (1LL * g[i+1] * (i+1)) % MOD;
}

int inv(int a) {
  int b = MOD, u = 0, v = 1;
  while (b) {
    int t = a / b;
    a -= t * b; swap(a, b);
    u -= t * v; swap(u, v);
  }
  return (u + MOD) % MOD;
}

void calc_fact() {
  fact.resize(input() + 1);
  inv_fact.resize(fact.size());
  fact[0] = 1;
  for (int i = 1; i < fact.size(); i++) fact[i] = (1LL * fact[i-1] * i) % MOD;
  inv_fact[fact.size()-1] = inv(fact[fact.size()-1]);
  for (int i = fact.size()-2; i >= 0; i--) inv_fact[i] = (1LL * inv_fact[i+1] * (i+1)) % MOD;
}

int acomb(int n, int x) {
  if (x < 0 || x > n) return 0;
  return (1LL * fact[n] * inv_fact[n-x]) % MOD;
}

int main(int argc, char** argv) {
  calc_fg();
  calc_fact();
  cout << acomb(f.size()-1, input()) << endl;
  return 0;
}
