vector<int> scc[MAXN];
int vis[MAXN];
int low[MAXN];
int num[MAXN];
int sccs;
stack<int> st;
int dfsTime;

void tarjan(int u) {
  low[u] = num[u] = dfsTime++;
  st.push(u);
  vis[u] = 1;
  for (int v : adj[u]) {
    if (!vis[v]) {
      tarjan(v);
      low[u] = min(low[u], low[v]);
    } else if (vis[v] == 1) {
      low[u] = min(low[u], num[v]);
    }
  }
  if (low[u] == num[u]) {
    int v;
    do {
      v = st.top();
      st.pop();
      scc[sccs].push_back(v);
      vis[v] = 2;
    } while (v != u);
    sccs++;
  }
}

int dfs(int u, int prohibited) {
  int ans = 0;
  vis[u] = 1;
  for (int v : adj[u]) {
    if (!vis[v] && v != prohibited) {
      ans = max(ans, 1 + dfs(v, prohibited));
    }
  }
  return ans;
}

