// Class
class TBig {
private:
  vector<int> a;

public:
  TBig(int x = 0) {
    while (x / 10) {
      a.push_back(x % 10);
      x /= 10;
    }
    a.push_back(x);
  }

  TBig operator+(const TBig &b) const {
    TBig c;
    int carry = 0;
    for (int i = 0; i < max(a.size(), b.a.size()); i++) {
      int d1 = i < a.size() ? a[i] : 0;
      int d2 = i < b.a.size() ? b.a[i] : 0;
      int sum = d1 + d2 + carry;
      c.a.push_back(sum % 10);
      carry = sum / 10;
    }
    if (carry) c.a.push_back(carry);
    return c;
  }

  TBig operator-(const TBig &b) const {
    TBig c;
    int carry = 0;
    for (int i = 0; i < max(a.size(), b.a.size()); i++) {
      int d1 = i < a.size() ? a[i] : 0;
      int d2 = i < b.a.size() ? b.a[i] : 0;
      int dif = d1 - d2 - carry;
      if (dif < 0) {
        dif += 10;
        carry = 1;
      } else
        carry = 0;
      c.a.push_back(dif);
    }
    while (c.a.size() > 1 && c.a.back() == 0) c.a.pop_back();
    return c;
  }

  TBig operator*(const int64_t &x) const {
    TBig c;
    int64_t carry = 0;
    for (int i = 0; i < a.size(); i++) {
      int64_t mul = static_cast<int64_t>(a[i]) * x + carry;
      c.a.push_back(mul % 10);
      carry = mul / 10;
    }
    if (carry) c.a.push_back(carry);
    return c;
  }

  TBig operator/(const int64_t &x) const {
    TBig c;
    int64_t rem = 0;
    for (int i = a.size() - 1; i >= 0; i--) {
      int64_t div = rem * 10 + a[i];
      c.a.push_back(div / x);
      rem = div % x;
    }
    while (c.a.size() > 1 && c.a.back() == 0) c.a.pop_back();
    reverse(c.a.begin(), c.a.end());
    return c;
  }

  TBig operator%(const int64_t &x) const {
    TBig c = *this;
    return c /= x;
  }

  bool operator<(const TBig &b) const {
    if (a.size() != b.a.size()) return a.size() < b.a.size();
    for (int i = a.size() - 1; i >= 0; i--) {
      if (a[i] != b.a[i]) return a[i] < b.a[i];
    }
    return false;
  }
};

