int bfs(vector<int> &bff, vector<bool> &seen, int n, int source, int start, int previous) {
    if (!seen[bff[source]]) {
        seen[source] = true;
        seen[bff[source]] = true;
        previous[source] = previous;
        return bfs(bff, seen, n, bff[source], start, source);
    } else if (previous == bff[source]) {
        seen[source] = true;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (!seen[i]) ans = max(ans, bfs(bff, seen, n, i, start, source));
        }
        return ans;
    } else {
        return bfs(bff, seen, n, bff[source], start, source);
    }
}

