bool isrev(int i, int j) {
    return (dr[i] == {-1, 1} && dc[j] == {1, -1}) || (dr[i] == {1, -1} && dc[j] == {-1, 1});
}

vector<int> attwho(int r, int c, const vector<vector<int>>& board) {
    vector<int> ans;
    for (int i = 0; i < 4; i++) {
        int nr = r + dr[i];
        int nc = c + dc[i];
        if (nr >= 0 && nr < medir && nc >= 0 && nc < medjc && board[nr][nc] > 0 && board[nr][nc] != board[r][c]) {
            ans.push_back(i);
        }
    }
    return ans;
}

void simul(int medir, const vector<vector<int>>& board) {
    for (int i = 0; i < medir; i++) {
        for (int j = 0; j < medjc; j++) {
            if (board[i][j] > 0) {
                vector<int> who = attwho(i, j, board);
                for (int k = 0; k < (int)who.size(); k++) {
                    nr = i + dr[who[k]];
                    nc = j + dc[who[k]];
                    if (board[nr][nc] > 0 && board[nr][nc] != board[i][j]) {
                        if (isrev(who[k], who[(k + 1) % (int)who.size()])) {
                            board[nr][nc] += board[i][j];
                        } else {
                            board[nr][nc] = max(board[nr][nc], board[i][j]);
                        }
                        board[i][j] = 0;
                        break;
                    }
                }
            }
        }
    }
}

bool forever(const vector<vector<int>>& board) {
    int cnta = 0, cntb = 0;
    for (int i = 0; i < medir; i++) {
        for (int j = 0; j < medjc; j++) {
            if (board[i][j] == 1) cnta++;
            if (board[i][j] == 2) cntb++;
        }
    }
    if (cnta > 0 && cntb > 0) return true;
    return false;
}

bool underthreat(const vector<vector<int>>& board) {
    for (int i = 0; i < medir; i++) {
        for (int j = 0; j < medjc; j++) {
            if (board[i][j] > 0) {
                for (int k = 0; k < 4; k++) {
                    int nr = i + dr[k];
                    int nc = j + dc[k];
                    if (nr >= 0 && nr < medir && nc >= 0 && nc < medjc && board[nr][nc] > 0 && board[nr][nc] != board[i][j]) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}

int calc() {
    int days = 0;
    while (true) {
        simul(medir, board);
        if (forever(board)) {
            days = -1;
            break;
        }
        if (!underthreat(board)) {
            break;
        }
        days++;
    }
    return days;
}

