      for (int mask = 0; mask < (1 << P - 1); mask++) {
        for (int j = 0; j < P - 1; j++) cost[mask] += (m[i][mask ^ (1 << j)] < m[i][mask ^ (1 << (j + 1))]);
      }
    }
    ans += *min_element(cost.begin(), cost.end());
    int mini = min_element(cost.begin(), cost.end()) - cost.begin();
    for (int i = 0; i < P; i++) {
      for (int mask = 0; mask < (1 << P - 1); mask++) {
        if ((mini >> i) & 1) swap(m[i][mask], m[i][mask ^ (1 << i)]);
      }
    }
    m.erase(m.begin() + mini);
    cost.erase(cost.begin() + mini);
  }
  return ans;
