std::vector<int> dijkstra(const std::vector<edge>& ar, int s, int n, int constraint) {
    std::vector<int> dist(n + 1, infty);
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> pq;
    dist[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        int d = pq.top().first, u = pq.top().second;
        pq.pop();
        if (d > dist[u])
            continue;
        for (const auto& e : ar)
            if (e.u == u && (constraint == 0 ? e.a <= d && d + e.b < dist[e.v] : e.a <= d && d + e.b <= dist[e.v])) {
                pq.push({d + e.b, e.v});
                dist[e.v] = d + e.b;
            }
    }
    return dist;
}

