string sort_f(string s, int n) {
  if (n == 1) return s;
  string left = sort_f(s.substr(0, n / 2), n / 2);
  string right = sort_f(s.substr(n / 2), n - n / 2);
  string res = "";
  int i = 0, j = 0;
  while (i < left.size() && j < right.size()) {
    if (left[i] < right[j]) res += left[i++];
    else res += right[j++];
  }
  while (i < left.size()) res += left[i++];
  while (j < right.size()) res += right[j++];
  return res;
}

