void add_edge(int from, int to, int cap) {
  e[e_cnt++] = Edge(from, to, cap, 0);
  g[from][g_cnt[from]++] = e_cnt - 1;
  e[e_cnt++] = Edge(to, from, 0, 0);
  g[to][g_cnt[to]++] = e_cnt - 1;
}

int bfs(int s, int t, int dist[]) {
  memset(dist, -1, sizeof(dist));
  queue<int> q;
  q.push(s);
  dist[s] = 0;
  while (!q.empty()) {
    int u = q.front();
    q.pop();
    for (int i = 0; i < g_cnt[u]; i++) {
      int id = g[u][i];
      int v = e[id].to;
      if (dist[v] == -1 && e[id].cap > e[id].flow) {
        q.push(v);
        dist[v] = dist[u] + 1;
      }
    }
  }
  return dist[t] != -1;
}

int dfs(int u, int t, int f, int dist[]) {
  if (u == t) return f;
  for (int i = 0; i < g_cnt[u]; i++) {
    int id = g[u][i];
    int v = e[id].to;
    if (dist[v] == dist[u] + 1 && e[id].cap > e[id].flow) {
      int pushed = dfs(v, t, min(f, e[id].cap - e[id].flow), dist);
      if (pushed > 0) {
        e[id].flow += pushed;
        e[id ^ 1].flow -= pushed;
        return pushed;
      }
    }
  }
  return 0;
}

