void solve(int test_number) {
  int n;
  long double u;
  cin >> n >> u;
  vector<long double> probs(n);
  long double total_sum = 0;
  long double total_product = 1;
  for (int i = 0; i < n; ++i) {
    cin >> probs[i];
    total_sum += probs[i];
    total_product *= probs[i];
  }
  sort(probs.rbegin(), probs.rend());
  long double sum = 0;
  long double best = total_product;
  for (int i = 0; i <= n; ++i) {
    if (i > 0) { sum += probs[i - 1]; }
    long double to_add = i - sum;
    if (to_add > u + eps) { continue; }
    long double left = u - to_add;
    if (i < n) {
      long double left_each = left / (long double)(n - i);
      if (probs[i] > left_each + eps) { continue; }
      long double result = 1;
      for (int j = 0; j < n - i; ++j) { result *= left_each; }
      best = max(best, result);
    } else {
      best = 1;
    }
  }
  cout << "Case #" << test_number << ": " << fixed << setprecision(9) << best
       << endl;
}
