  if (L > R)return 1;
  if (DP[L][R] != -1)return DP[L][R];
  DP[L][R] = 0;
  REP(i, L, R + 1)
    if (!conflict(sub[i], x) and !conflict(x, sub[i]))DP[L][R] = (DP[L][R] + go(L, i - 1, sub[i]) % fact[R - L + 1] + go(i + 1, R, sub[i]) % fact[R - L + 1]) % fact[R - L + 1];
  return DP[L][R];
}

