int advance(int idx) {
  if (s[idx] == '*') return (1 << 14) - 1;
  if (s[idx] == '|') return (1 << 15) - 1;
  if (s[idx] == ')') return advance(idx - 1);
  int ans = 0;
  if (s[idx] == '(')
    ans = advance(idx + 1);
  else
    ans = (1 << idx);
  return ans;
}
int rec(int idx, int eq, int possc, int z) {
  if (idx == l) {
    if (eq) return 1;
    return 0;
  }
  int &ret = dp[idx][eq][possc][z];
  if (~ret) return ret;
  ret = 0;
  if (s[idx] == '*')
    ret |= rec(idx + 1, eq, possc, z);
  if (s[idx] == '|')
    ret |= rec(idx + 1, eq, possc, z);
  int temp = possc;
  if (s[idx] == '(')
    temp = advance(idx + 1);
  else if (s[idx] == ')')
    temp = advance(idx - 1);
  if (s[idx] <= '9' && s[idx] >= '0') {
    int p = (s[idx] - '0');
