  go(str + 1, serv, mask, cur);
  if (trie[have[str].ch[trie[serv].f]].l > 0) {
    mask |= (1 << str);
    go(str + 1, serv + 1, mask, cur + trie[have[str].ch[trie[serv].f]].l);
    mask ^= (1 << str);
  }
}

