double calc2(int *x, int *y, int i, double line) {
  double dx = x[1] - x[0];
  double dy = y[1] - y[0];
  return y[0] + dy / dx * (line - x[0]);
}
double calc(int l, int u, double x) {
  return calc2(Lx + l, Ly + l, l, x) - calc2(Ux + u, Uy + u, u, x);
}
double solve(double now, double tar) {
  double l = 0, r = W, mid;
