    mid = (l + r) / 2;
    double p = calc(0, u - 1, mid);
    p -= calc(l, u - 1, mid);
    if (p > tar) {
      l = mid + eps;
    } else if (p < tar) {
      r = mid - eps;
    } else {
      return mid;
    }
