  h.resize(N);
  canwin.resize(N);
  canlose.resize(N);
  int ca = getNum();
  int cb = getNum();
  P = getNum();
  Q = getNum();
  N = getNum();
  for (int i = 0; i < N; ++i) {
    g[i] = getNum();
    h[i] = getNum();
  }
  int gsum = 0;
  int hsum = 0;
  for (int i = 0; i < N; ++i) {
    gsum += g[i];
    hsum += h[i];
  }
  if (gsum <= hsum) {
    printf("Case #%d: 0\n", ++cnum);
    return;
  }
  if (Q > P) {
    for (int t = N - 1; t >= 0; --t) {
      canlose[t] = (h[t] + Q) / P;
      if (t == N - 1) {
        canwin[t] = ca;
      } else {
        canwin[t] = h[t] + Q;
      }
    }
  } else {
    for (int t = N - 1; t >= 0; --t) {
      canwin[t] = (g[t] + P) / Q;
      if (t == N - 1) {
        canlose[t] = cb;
      } else {
        canlose[t] = g[t] + P;
      }
    }
  }
  int mincanlose = INT_MAX;
  for (int t = N - 1; t >= 0; --t) {
    mincanlose = min(mincanlose, canlose[t]);
    if (canwin[t] >= mincanlose) {
      printf("Case #%d: %d\n", ++cnum, t + 1);
      return;
    }
  }
  printf("Case #%d: -1\n", ++cnum);
}

