double area(const Point& a, const Point& b, const Point& c) {
  return (a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y)) / 2;
}

double scaleFactor(const double& a1, const double& A1) {
  return a1 / A1;
}

double translationFactorX(const double& tx, const double& s) {
  return tx * s;
}

double translationFactorY(const double& ty, const double& s) {
  return ty * s;
}

double angleOfRotation(const double& tx, const double& ty) {
  return atan2(ty, tx);
}

double coefficientA(const double& area1, const double& area2, const double& theta, const double& tx, const double& ty) {
  return (area1 * cos(theta) + area2 * sin(theta) + tx * sin(theta) - ty * cos(theta)) / (area1 * sin(theta) - area2 * cos(theta) + tx * cos(theta) + ty * sin(theta));
}

double coefficientB(const double& area1, const double& area2, const double& theta, const double& tx, const double& ty) {
  return (area1 * sin(theta) - area2 * cos(theta) + tx * cos(theta) + ty * sin(theta)) / (area1 * cos(theta) + area2 * sin(theta) + tx * sin(theta) - ty * cos(theta));
}

Point intersectionPoint(const double& A, const double& B) {
  Point p;
  p.x = -B / A;
  p.y = 1;
  return p;
}

