using namespace std;

int next() {
  int x;
  cin >> x;
  return x;
}

int w, h;

bool in(int x, int l, int r) {
  return l <= x && x <= r;
}

vector<int> ptr;
vector<vector<map<int, int>>> flow, cap, edges;
vector<int> queue, d;
int S, T, V;
const int INF = 1e9;

void bfs() {
  queue.clear();
  d.assign(V, INF);
  queue.push_back(S);
  d[S] = 0;
  while (!queue.empty()) {
    int u = queue.front();
    queue.erase(queue.begin());
    for (auto &e : edges[u]) {
      int v = e.first;
      if (d[v] == INF && cap[u][v] > flow[u][v]) {
        queue.push_back(v);
        d[v] = d[u] + 1;
      }
    }
  }
}

int dfs(int u, int f) {
  if (u == T) return f;
  for (auto &it = ptr[u]; it != edges[u].end(); ++it) {
    int v = it->first;
    if (d[v] == d[u] + 1 && cap[u][v] > flow[u][v]) {
      int df = dfs(v, min(f, cap[u][v] - flow[u][v]));
      if (df > 0) {
        flow[u][v] += df;
        flow[v][u] -= df;
        return df;
      }
    }
  }
  return 0;
}

int dinic() {
  int max_flow = 0;
  while (true) {
    bfs();
    if (d[T] == INF) break;
    ptr.assign(V, edges[S].begin());
    while (int f = dfs(S, INF)) max_flow += f;
  }
  return max_flow;
}

void solve() {
  w = next(), h = next();
  V = w * h + 2;
  S = V - 2, T = V - 1;
  flow.assign(V, vector<map<int, int>>(V));
  cap.assign(V, vector<map<int, int>>(V));
  edges.assign(V, vector<pair<int, int>>());
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      int x = next();
      if (in(i, 0, h - 2)) {
        edges[S].push_back({i * w + j + 1, x});
        cap[S][i * w + j + 1] += x;
      }
      if (in(i, 1, h - 1)) {
        edges[i * w + j + 1].push_back({S, 0});
        edges[i * w + j + 1].push_back({i * w + j, x});
        edges[i * w + j].push_back({i * w + j + 1, x});
        cap[i * w + j + 1][S] += x;
        cap[i * w + j + 1][i * w + j] += x;
        cap[i * w + j][i * w + j + 1] += x;
      }
      if (in(i, 2, h - 1)) {
        edges[i * w + j + 1].push_back({T, x});
        cap[i * w + j + 1][T] += x;
      }
    }
  }
  cout << dinic() << endl;
}

int main() {
  solve();
  return 0;
}
