  vector<int> seen;
  for (int i = 0; i < lim; i++) {
    if (num == 1) {
      return true;
    }
    num = tobase(num * num, base);
    if (find(seen.begin(), seen.end(), num) != seen.end()) {
      return false;
    }
    seen.push_back(num);
  }
  return false;
}

